import java.util.*;
import java.io.*;

public class Main {
    static long[][] comb = new long[62][62];
    static long[][] A = new long[32][32];
    static long[][] B = new long[32][32];
    static long totalComb;
    static int R, C, n;
    static char[] p = new char[110];
    static long[][] CC = new long[32][32];
    static long answer;
    static long totalAnswer = 0;
    static List<Pair>[][][] P = new ArrayList[32][2][];
    static List<Pair>[][][] Q = new ArrayList[32][2][];
    static {
        for (int i = 0; i < 32; i++) {
            for (int j = 0; j < 2; j++) {
                P[i][j] = new ArrayList[0];
                Q[i][j] = new ArrayList[0];
            }
        }
    }

    static class Pair implements Comparable<Pair> {
        long first, second;
        Pair(long f, long s) {
            this.first = f;
            this.second = s;
        }
        public int compareTo(Pair o) {
            if (this.first != o.first) return Long.compare(this.first, o.first);
            return Long.compare(this.second, o.second);
        }
    }

    static List<Pair>[][][] PList = new ArrayList[32][2][];
    static List<Pair>[][][] QList = new ArrayList[32][2][];
    static {
        for (int i = 0; i < 32; i++) {
            for (int j = 0; j < 2; j++) {
                PList[i][j] = new ArrayList[0];
                QList[i][j] = new ArrayList[0];
            }
        }
    }

    static void addPath(int x, int y, long g, long c1, long c2, int ck) {
        if (x + y == R + n) {
            P[x][ck].add(new Pair(g, c1));
            if (c2 > 0) Q[x][ck].add(new Pair(g, c2));
            return;
        }
        addPath(x + 1, y, g + (! (ck != 0) ? A[x + 1][y] : 0), c1, (p[x + y] != 'B' ? c2 : 0), ck);
        addPath(x, y + 1, g + (ck != 0 ? B[x][y + 1] : 0), c1, (p[x + y] != 'A' ? c2 : 0), ck);
    }

    static void calcMin(int x, int y, long g, int ck) {
        if (x + y == R + n) {
            if (P[x][ck].isEmpty()) return;
            int t = lowerBound(P[x][ck], new Pair((totalComb + 1) / 2 - g, 0));
            if (t != P[x][ck].size() && P[x][ck].get(t).second > 0) {
                long tp = (P[x][ck].get(t).first + g) * 2 - totalComb;
                if (tp < 0) tp = -tp;
                if (answer > tp) answer = tp;
            }
            if (t > 0 && P[x][ck].get(t - 1).second > 0) {
                long tp = (P[x][ck].get(t - 1).first + g) * 2 - totalComb;
                if (tp < 0) tp = -tp;
                if (answer > tp) answer = tp;
            }
            return;
        }
        calcMin(x - 1, y, g + (! (ck != 0) ? A[x][y] : 0), ck);
        calcMin(x, y - 1, g + (ck != 0 ? B[x][y] : 0), ck);
    }

    static void calcMax(int x, int y, long g, int ck) {
        if (x + y == R + n) {
            int t = lowerBound(Q[x][ck], new Pair((totalComb + 1) / 2 - g, 0));
            if (t != Q[x][ck].size() && Q[x][ck].get(t).second > 0) {
                long tp = (Q[x][ck].get(t).first + g) * 2 - totalComb;
                if (tp < 0) tp = -tp;
                if (answer == tp) {
                    totalAnswer += Q[x][ck].get(t).second;
                }
            }
            if (t > 0 && Q[x][ck].get(t - 1).second > 0) {
                long tp = (Q[x][ck].get(t - 1).first + g) * 2 - totalComb;
                if (tp < 0) tp = -tp;
                if (answer == tp) {
                    totalAnswer += Q[x][ck].get(t - 1).second;
                }
            }
            return;
        }
        if (p[x + y - 1] != 'B') calcMax(x - 1, y, g + (! (ck != 0) ? A[x][y] : 0), ck);
        if (p[x + y - 1] != 'A') calcMax(x, y - 1, g + (ck != 0 ? B[x][y] : 0), ck);
    }

    static void compress(List<Long> P) {
        if (P.isEmpty()) return;
        Collections.sort(P);
        int cnt = 0;
        long sum = 0;
        List<Long> newP = new ArrayList<>();
        for (int i = 0; i < P.size(); i++) {
            sum += P.get(i);
            if (i == P.size() - 1 || !P.get(i).equals(P.get(i + 1))) {
                newP.add(P.get(i));
                cnt++;
                sum = 0;
            }
        }
        P.clear();
        P.addAll(newP);
    }

    static int lowerBound(List<Pair> list, Pair key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid).compareTo(key) < 0) low = mid + 1;
            else high = mid;
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        R = Integer.parseInt(st.nextToken());
        C = Integer.parseInt(st.nextToken());
        String line = br.readLine();
        p = line.toCharArray();

        for (int i = 0; i <= 60; i++) {
            comb[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
            }
        }
        n = R + C;
        totalComb = comb[n * 2][R * 2];

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (i > 0) A[i][j] = comb[i - 1][R - 1] * (comb[n * 2 - i][R] - comb[j][R]);
                if (j > 0) B[i][j] = comb[j - 1][R - 1] * (comb[n * 2 - j][R] - comb[i][R]);
            }
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < 2; j++) {
                P[i][j] = new ArrayList<>();
                Q[i][j] = new ArrayList<>();
            }
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < 2; j++) {
                compress(P[i][j]);
                compress(Q[i][j]);
            }
        }

        answer = totalComb + 1;
        calcMin(n, n, 0, 0);
        calcMin(n, n, 0, 1);
        calcMax(n, n, 0, 0);
        calcMax(n, n, 0, 1);
        System.out.println(answer);
    }
}
